<?php require 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$stmt=$pdo->prepare('SELECT * FROM users WHERE email=?');$stmt->execute([trim($_POST['email']??'')]);$u=$stmt->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['name']=$u['name'];$_SESSION['role']=$u['role'];go('index.php');}$error='Invalid email or password.';}require 'header.php';?><div class="formbox"><h1>Login</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button></form></div><?php require 'footer.php';?>